source='''from collections import Counter

def transform(grid):
    a=[row[:] for row in grid]
    h,w=len(a),len(a[0])
    bg=Counter(x for row in a for x in row).most_common(1)[0][0]
    candidates=[]
    for axis, n, m in ((0,h,w),(1,w,h)):
        lines=[]
        for i in range(n):
            vals=a[i] if axis==0 else [a[r][i] for r in range(h)]
            if len(set(vals))==1 and vals[0]!=bg:
                lines.append((i, vals[0]))
        if lines:
            candidates.append((len(lines),axis,n,m,lines))
    if not candidates:
        return a
    _,axis,n,m,lines=max(candidates,key=lambda z:z[0])
    # Use the spacing between repeated divider lines as the tile period.
    same=[i for i,c in lines if c==lines[0][1]]
    if len(same)>=2:
        period=same[1]-same[0]
        divider=same[0]
        before=[(divider-period+1+j) for j in range(period)]
        after=[divider+1+j for j in range(period)]
        def score(indices):
            return sum(1 for i in indices if 0<=i<n for k in range(m)
                       if (a[i][k] if axis==0 else a[k][i]) not in (bg, lines[0][1]))
        src=after if score(after)>score(before) else before
        src=[i for i in src if 0<=i<n]
        if len(src)!=period:
            src=before if len(before)==period and before[0]>=0 else after
    else:
        divider=same[0]
        period=divider+1
        src=list(range(period))
    if period<=0 or len(src)!=period:
        return a
    tile=[]
    for i in src:
        tile.append((a[i][:] if axis==0 else [a[r][i] for r in range(h)]))
    # Repeat the selected tile over the full dimension, including the seed area.
    for i in range(n):
        row_index=i%period
        if axis==0:
            a[i]=tile[row_index][:]
        else:
            col=tile[row_index]
            for r in range(h):
                a[r][i]=col[r]
    return a
'''
